local function setupColorPickerVisuals(frame2, frame3)
	local rainbowGradient = Instance.new("UIGradient", frame2)
	rainbowGradient.Color = ColorSequence.new({
		ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 0, 0)),
		ColorSequenceKeypoint.new(0.16, Color3.fromRGB(255, 0, 255)),
		ColorSequenceKeypoint.new(0.33, Color3.fromRGB(0, 0, 255)),
		ColorSequenceKeypoint.new(0.5, Color3.fromRGB(0, 255, 255)),
		ColorSequenceKeypoint.new(0.66, Color3.fromRGB(0, 255, 0)),
		ColorSequenceKeypoint.new(0.83, Color3.fromRGB(255, 255, 0)),
		ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 0, 0))
	})

	local whiteOverlay = Instance.new("Frame", frame2)
	whiteOverlay.Size = UDim2.new(1, 0, 1, 0)
	whiteOverlay.BackgroundTransparency = 0
	whiteOverlay.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
	whiteOverlay.BorderSizePixel = 0
	whiteOverlay.ZIndex = frame2.ZIndex + 1
	Instance.new("UICorner", whiteOverlay).CornerRadius = UDim.new(0, 3)

	local whiteGradient = Instance.new("UIGradient", whiteOverlay)
	whiteGradient.Rotation = 90 
	whiteGradient.Transparency = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 1),
		NumberSequenceKeypoint.new(1, 0.25)
	})

	local pickerDot = Instance.new("Frame", frame2)
	pickerDot.Size = UDim2.new(0, 8, 0, 8)
	pickerDot.AnchorPoint = Vector2.new(0.5, 0.5)
	pickerDot.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
