local function createColorEngine(f2, f3, pDot, dDot, dGrad, targetBtn)
	local hue, sat, vibe = 0, 0, 1
	local selCol, selDark = false, false

	local function update()
		local adjSat = math.clamp(sat, 0.25, 1)
		local base = Color3.fromHSV(hue, adjSat, 1)
		dGrad.Color = ColorSequence.new({
			ColorSequenceKeypoint.new(0, base),
			ColorSequenceKeypoint.new(1, Color3.fromRGB(0, 0, 0))
		})
		local final = base:Lerp(Color3.fromRGB(0, 0, 0), 1 - vibe)
		targetBtn.BackgroundColor3 = final
	end

	f2.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then selCol = true end
	end)
	f3.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then selDark = true end
	end)

	UIS.InputChanged:Connect(function(input)
		if (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
			if selCol then
				local rX = input.Position.X - f2.AbsolutePosition.X
				local rY = input.Position.Y - f2.AbsolutePosition.Y
				local pX = math.clamp(rX / f2.AbsoluteSize.X, 0, 1)
				local pY = math.clamp(rY / f2.AbsoluteSize.Y, 0, 1)
				pDot.Position = UDim2.new(pX, 0, pY, 0)
				hue = 1 - pX
				sat = 1 - (pY * 0.75)
				update()
			elseif selDark then
				local rX = input.Position.X - f3.AbsolutePosition.X
				local pX = math.clamp(rX / f3.AbsoluteSize.X, 0, 1)
				dDot.Position = UDim2.new(pX, 0, -0.1, 0)
				vibe = 1 - pX
				update()
			end
		end
	end)

	UIS.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			selCol = false selDark = false
		end
	end)
end

createColorEngine(LMG2L["Frame2_25"], LMG2L["Frame3_27"], mainDot, mainDarkDot, mainDarkGrad, LMG2L["Color_3"])
createColorEngine(LMG2L["Frame2_14"], LMG2L["Frame3_16"], strokeDot, strokeDarkDot, strokeDarkGrad, LMG2L["St_21"])


